//! Feature-gated Arbitrary implementations for local lattice aggregate types.
//!
//! Each coordinate independently selects a sanitized finite binary64 or an i128,
//! then imports its exact value into Real. These seeds are dyadic rationals, with
//! finite-float extremes/subnormals and signed integers reachable; symbolic,
//! non-dyadic, and general algebraic sources are not generated by these helpers.
//! No unit, invertibility, affine-transform, or geometric validity constraints apply.
//!
//! The primitive finite_f64 helper maps NaN/infinity bit patterns to +0.0 before the
//! checked scalar import. This intentional fuzz distribution is not a general input
//! conversion policy. The mathematical scalar treats either floating zero as zero.
//! Manual implementations retain Arbitrary's default size hint (0,None); with the
//! current zero-padding integer decoder, empty bytes can yield all-zero objects.
//! Generation order follows coordinate/row order and shares one Unstructured cursor.
//! Byte size bounds seed encodings, not downstream arithmetic work or memory.

use arbitrary::{Arbitrary, Error, Unstructured};

use crate::{Complex, Matrix3, Matrix4, Real, Vector2, Vector3, Vector4};

/// Decode a u64 bit pattern as f64, retaining finite values and replacing every NaN/infinity with +0.0.
///
/// Finite subnormals and negative zero are reachable at this primitive stage. This
/// is a fuzz-input sanitization rule, not a valid Real conversion of a nonfinite
/// number. Arbitrary 1.4.2 zero-pads short integer input; missing bytes need not fail.
fn finite_f64(u: &mut Unstructured<'_>) -> arbitrary::Result<f64> {
    let bits = u64::arbitrary(u)?;
    let f = f64::from_bits(bits);
    if f.is_finite() { Ok(f) } else { Ok(0.0) }
}

/// Choose a finite binary64 import or an i128 integer with ratio(1,2), then construct an exact Real.
///
/// The two routes produce dyadic rationals/integers, not arbitrary symbolic or
/// non-dyadic rational data. Selection follows input bytes rather than a uniform
/// mathematical-value distribution. Native float-conversion errors map to
/// IncorrectFormat. Current primitive decoding zero-pads missing bytes, so even
/// empty input can produce zero; this helper does not enforce a minimum input size.
fn arbitrary_real(u: &mut Unstructured<'_>) -> arbitrary::Result<Real> {
    if u.ratio(1, 2)? {
        Real::try_from(finite_f64(u)?).map_err(|_| Error::IncorrectFormat)
    } else {
        Ok(Real::from(i128::arbitrary(u)?))
    }
}

impl<'a> Arbitrary<'a> for Complex {
    /// Generate 2 exact dyadic/integer coordinates in real then imaginary order and pass them to Complex::new.
    ///
    /// Uses one input cursor, propagates the first generation error, and adds no
    /// normalization or geometric/algebraic validity check. No custom size hint is supplied.
    fn arbitrary(u: &mut Unstructured<'a>) -> arbitrary::Result<Self> {
        Ok(Self::new(arbitrary_real(u)?, arbitrary_real(u)?))
    }
}

impl<'a> Arbitrary<'a> for Vector2 {
    /// Generate 2 exact dyadic/integer coordinates in x,y order and pass them to Vector2::new.
    ///
    /// Uses one input cursor, propagates the first generation error, and adds no
    /// normalization or geometric/algebraic validity check. No custom size hint is supplied.
    fn arbitrary(u: &mut Unstructured<'a>) -> arbitrary::Result<Self> {
        Ok(Self::new([arbitrary_real(u)?, arbitrary_real(u)?]))
    }
}

impl<'a> Arbitrary<'a> for Vector3 {
    /// Generate 3 exact dyadic/integer coordinates in x,y,z order and pass them to Vector3::new.
    ///
    /// Uses one input cursor, propagates the first generation error, and adds no
    /// normalization or geometric/algebraic validity check. No custom size hint is supplied.
    fn arbitrary(u: &mut Unstructured<'a>) -> arbitrary::Result<Self> {
        Ok(Self::new([
            arbitrary_real(u)?,
            arbitrary_real(u)?,
            arbitrary_real(u)?,
        ]))
    }
}

impl<'a> Arbitrary<'a> for Vector4 {
    /// Generate 4 exact dyadic/integer coordinates in array order and pass them to Vector4::new.
    ///
    /// Uses one input cursor, propagates the first generation error, and adds no
    /// normalization or geometric/algebraic validity check. No custom size hint is supplied.
    fn arbitrary(u: &mut Unstructured<'a>) -> arbitrary::Result<Self> {
        Ok(Self::new([
            arbitrary_real(u)?,
            arbitrary_real(u)?,
            arbitrary_real(u)?,
            arbitrary_real(u)?,
        ]))
    }
}

impl<'a> Arbitrary<'a> for Matrix3 {
    /// Generate 9 exact dyadic/integer coordinates in row-major order and pass them to Matrix3::new.
    ///
    /// Uses one input cursor, propagates the first generation error, and adds no
    /// normalization or geometric/algebraic validity check. No custom size hint is supplied.
    fn arbitrary(u: &mut Unstructured<'a>) -> arbitrary::Result<Self> {
        Ok(Self::new([
            [arbitrary_real(u)?, arbitrary_real(u)?, arbitrary_real(u)?],
            [arbitrary_real(u)?, arbitrary_real(u)?, arbitrary_real(u)?],
            [arbitrary_real(u)?, arbitrary_real(u)?, arbitrary_real(u)?],
        ]))
    }
}

impl<'a> Arbitrary<'a> for Matrix4 {
    /// Generate 16 exact dyadic/integer coordinates in row-major order and pass them to Matrix4::new.
    ///
    /// Uses one input cursor, propagates the first generation error, and adds no
    /// normalization or geometric/algebraic validity check. No custom size hint is supplied.
    fn arbitrary(u: &mut Unstructured<'a>) -> arbitrary::Result<Self> {
        Ok(Self::new([
            [
                arbitrary_real(u)?,
                arbitrary_real(u)?,
                arbitrary_real(u)?,
                arbitrary_real(u)?,
            ],
            [
                arbitrary_real(u)?,
                arbitrary_real(u)?,
                arbitrary_real(u)?,
                arbitrary_real(u)?,
            ],
            [
                arbitrary_real(u)?,
                arbitrary_real(u)?,
                arbitrary_real(u)?,
                arbitrary_real(u)?,
            ],
            [
                arbitrary_real(u)?,
                arbitrary_real(u)?,
                arbitrary_real(u)?,
                arbitrary_real(u)?,
            ],
        ]))
    }
}
